     1	package br.com.maretalta.report;
     2	
     3	import br.com.maretalta.ApiException;
     4	import br.com.maretalta.domain.Reservation;
     5	
     6	import java.time.LocalDate;
     7	import java.time.YearMonth;
     8	import java.time.format.DateTimeParseException;
     9	import java.util.Comparator;
    10	import java.util.List;
    11	
    12	/** Shared helpers for building the reports: layout, period parsing and reservation selection. */
    13	final class Csv {
    14	    static final String INN = "Pousada Maré Alta";
    15	
    16	    private Csv() {}
    17	
    18	    /** Title line, header, body rows and the closing total line, each terminated by a newline. */
    19	    static String build(String reportName, String period, String header, List<String> rows, String total) {
    20	        StringBuilder sb = new StringBuilder();
    21	        sb.append(INN).append(',').append(reportName).append(',').append(period).append('\n');
    22	        sb.append(header).append('\n');
    23	        rows.forEach(r -> sb.append(r).append('\n'));
    24	        sb.append(total).append('\n');
    25	        return sb.toString();
    26	    }
    27	
    28	    static LocalDate parseDate(String raw) {
    29	        if (raw == null) throw ApiException.invalid("date is required (yyyy-MM-dd)");
    30	        try {
    31	            return LocalDate.parse(raw);
    32	        } catch (DateTimeParseException e) {
    33	            throw ApiException.invalid("date must be in the format yyyy-MM-dd");
    34	        }
    35	    }
    36	
    37	    static YearMonth parseMonth(String raw) {
    38	        if (raw == null) throw ApiException.invalid("month is required (yyyy-MM)");
    39	        if (!raw.matches("\\d{4}-\\d{2}")) throw ApiException.invalid("month must be in the format yyyy-MM");
    40	        try {
    41	            return YearMonth.parse(raw);
    42	        } catch (DateTimeParseException e) {
    43	            throw ApiException.invalid("month must be in the format yyyy-MM");
    44	        }
    45	    }
    46	
    47	    static final Comparator<Reservation> BY_CHECK_IN_THEN_ID =
    48	            Comparator.<Reservation, LocalDate>comparing(r -> r.checkIn).thenComparingInt(r -> r.id);
    49	
    50	    static List<Reservation> startingIn(List<Reservation> all, YearMonth month) {
    51	        return all.stream()
    52	                .filter(r -> YearMonth.from(r.checkIn).equals(month))
    53	                .sorted(BY_CHECK_IN_THEN_ID)
    54	                .toList();
    55	    }
    56	
    57	    /** Reservations starting in the month that left money with the inn (paid minus refunded > 0). */
    58	    static List<Reservation> revenueReservations(List<Reservation> all, YearMonth month) {
    59	        return startingIn(all, month).stream().filter(r -> r.netAmount().signum() > 0).toList();
    60	    }
    61	}
