     6	
     7	import java.time.LocalDate;
     8	import java.util.Comparator;
     9	import java.util.List;
    10	
    11	public class OccupancyReport implements Report {
    12	    private final ReservationService service;
    13	
    14	    public OccupancyReport(ReservationService service) {
    15	        this.service = service;
    16	    }
    17	
    18	    @Override public String name() { return "occupancy"; }
    19	
    20	    @Override public String paramName() { return "date"; }
    21	
    22	    @Override
    23	    public String generate(String rawParam) {
    24	        LocalDate date = Csv.parseDate(rawParam);
    25	        List<Reservation> occupying = service.read(all -> all.stream()
    26	                .filter(r -> r.status.isPaid() && !date.isBefore(r.checkIn) && date.isBefore(r.checkOut))
    27	                .sorted(Comparator.<Reservation>comparingInt(r -> r.room.number()).thenComparingInt(r -> r.id))
    28	                .toList());
    29	        List<String> rows = occupying.stream()
    30	                .map(r -> String.join(",", String.valueOf(r.room.number()), r.room.type().name(),
    31	                        String.valueOf(r.id), r.checkIn.toString(), r.checkOut.toString()))
    32	                .toList();
    33	        long occupiedRooms = occupying.stream().map(r -> r.room.number()).distinct().count();
    34	        List<Room> rooms = service.rooms();
    35	        return Csv.build(name(), date.toString(), "room,type,reservation,check_in,check_out", rows,
    36	                "total," + occupiedRooms + "/" + rooms.size());
    37	    }
    38	}
