    31	            BigDecimal totalAmount = Money.ZERO;
    32	            for (RatePlan plan : RatePlan.values()) {
    33	                List<Reservation> ofPlan = rs.stream().filter(r -> r.ratePlan == plan).toList();
    34	                BigDecimal amount = ofPlan.stream().map(Reservation::netAmount).reduce(Money.ZERO, BigDecimal::add);
