=== report/TourismTaxPolicy.java
     1	package br.com.maretalta.report;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.util.HashMap;
     6	import java.util.Map;
     7	
     8	/** Municipal tax per guest per night; the city changes it yearly, so it is looked up by the stay's check-in year. */
     9	public class TourismTaxPolicy {
    10	    public static final BigDecimal DEFAULT_RATE = new BigDecimal("4.50");
    11	
    12	    private final BigDecimal defaultRate;
    13	    private final Map<Integer, BigDecimal> rateByYear;
    14	
    15	    public TourismTaxPolicy(BigDecimal defaultRate, Map<Integer, BigDecimal> rateByYear) {
    16	        this.defaultRate = defaultRate;
    17	        this.rateByYear = Map.copyOf(rateByYear);
    18	    }
    19	
    20	    public BigDecimal ratePerGuestNight(LocalDate checkIn) {
    21	        return rateByYear.getOrDefault(checkIn.getYear(), defaultRate);
    22	    }
    23	
    24	    /**
    25	     * @param defaultRate fallback rate, e.g. "4.50" (null = 4.50)
    26	     * @param yearly      per-year overrides such as "2027=4.80,2028=5.00" (may be null)
    27	     */
    28	    public static TourismTaxPolicy parse(String defaultRate, String yearly) {
    29	        Map<Integer, BigDecimal> byYear = new HashMap<>();
    30	        if (yearly != null && !yearly.isBlank()) {
    31	            for (String entry : yearly.split(",")) {
    32	                String[] kv = entry.trim().split("=");
    33	                byYear.put(Integer.parseInt(kv[0].trim()), new BigDecimal(kv[1].trim()));
    34	            }
    35	        }
    36	        BigDecimal base = defaultRate == null || defaultRate.isBlank() ? DEFAULT_RATE : new BigDecimal(defaultRate.trim());
    37	        return new TourismTaxPolicy(base, byYear);
    38	    }
    39	}
