    25	        return Money.round(policy.ratePerGuestNight(r.checkIn).multiply(BigDecimal.valueOf((long) r.guests * r.nights)));
    26	    }
    27	
    28	    @Override
    29	    public String generate(String rawParam) {
    30	        YearMonth month = Csv.parseMonth(rawParam);
    31	        return service.read(all -> {
    32	            List<Reservation> rs = Csv.startingIn(all, month).stream().filter(r -> r.status.isPaid()).toList();
    33	            List<String> rows = rs.stream()
    34	                    .map(r -> String.join(",", String.valueOf(r.id), String.valueOf(r.room.number()),
    35	                            r.checkIn.toString(), r.checkOut.toString(), String.valueOf(r.guests),
    36	                            String.valueOf(r.nights), Money.plain(taxOf(r))))
    37	                    .toList();
    38	            BigDecimal sum = rs.stream().map(this::taxOf).reduce(Money.ZERO, BigDecimal::add);
    39	            return Csv.build(name(), month.toString(), "reservation,room,check_in,check_out,guests,nights,tax",
    40	                    rows, "total," + Money.plain(sum));
    41	        });
