    85	    private static ReservationService.Request parseRequest(Context ctx) {
    86	        JsonNode body;
    87	        try {
    88	            body = JSON.readTree(ctx.bodyAsBytes());
    89	        } catch (Exception e) {
    90	            throw ApiException.invalid("Body must be valid JSON");
    91	        }
    92	        if (body == null || !body.isObject()) {
    93	            throw ApiException.invalid("Body must be a JSON object");
    94	        }
    95	        int roomNumber = integer(body, "roomNumber");
    96	        String name = text(body, "guestName");
    97	        String email = text(body, "guestEmail");
    98	        String cpf = text(body, "guestCpf");
    99	        LocalDate checkIn = date(body, "checkIn");
   100	        LocalDate checkOut = date(body, "checkOut");
   101	        int guests = integer(body, "guests");
   102	        RatePlan plan;
   103	        try {
   104	            plan = RatePlan.valueOf(text(body, "ratePlan"));
   105	        } catch (IllegalArgumentException e) {
   106	            throw ApiException.invalid("ratePlan must be STANDARD or NON_REFUNDABLE");
   107	        }
