   119	    private static int integer(JsonNode body, String field) {
   120	        JsonNode n = body.get(field);
   121	        if (n == null || !n.isIntegralNumber() || !n.canConvertToInt()) {
   122	            throw ApiException.invalid(field + " must be an integer");
   123	        }
   124	        return n.intValue();
   125	    }
   126	
   127	    private static LocalDate date(JsonNode body, String field) {
   128	        String raw = text(body, field);
   129	        try {
   130	            return LocalDate.parse(raw);
   131	        } catch (DateTimeParseException e) {
   132	            throw ApiException.invalid(field + " must be in the format yyyy-MM-dd");
   133	        }
   134	    }
