     9	public final class Money {
    10	    public static final BigDecimal ZERO = new BigDecimal("0.00");
    11	
    12	    private Money() {}
    13	
    14	    /** Rounds to cents, half-even. */
    15	    public static BigDecimal round(BigDecimal value) {
    16	        return value.setScale(2, RoundingMode.HALF_EVEN);
    17	    }
    18	
    19	    /** "R$ 1.234,56" */
    20	    public static String brl(BigDecimal value) {
    21	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.of("pt", "BR"));
    22	        symbols.setGroupingSeparator('.');
    23	        symbols.setDecimalSeparator(',');
    24	        DecimalFormat format = new DecimalFormat("#,##0.00", symbols);
    25	        format.setRoundingMode(RoundingMode.HALF_EVEN);
    26	        return "R$ " + format.format(round(value));
    27	    }
    28	
    29	    /** "599.76" */
    30	    public static String plain(BigDecimal value) {
    31	        return round(value).toPlainString();
    32	    }
    33	}
