   295	public class ReservationService {
   296	    public static final String EMAIL_SUBJECT = "Reserva confirmada - Pousada Maré Alta";
   297	
   298	    public record Request(int roomNumber, String guestName, String guestEmail, String guestCpf,
   299	                          LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {}
   300	
   301	    private final List<Room> rooms = List.of(
   302	            new Room(101, RoomType.STANDARD),
   303	            new Room(102, RoomType.STANDARD),
   304	            new Room(201, RoomType.DELUXE),
   305	            new Room(202, RoomType.DELUXE),
   306	            new Room(301, RoomType.SUITE));
   307	    private final List<Reservation> reservations = new ArrayList<>();
   308	    private final Outbox outbox;
   309	
   310	    public ReservationService(Outbox outbox) {
   311	        this.outbox = outbox;
   312	    }
   313	
   314	    public List<Room> rooms() {
   315	        return rooms;
   316	    }
   317	
   318	    public synchronized Reservation create(Request req) {
   319	        if (!req.checkOut().isAfter(req.checkIn())) {
   320	            throw ApiException.invalid("checkOut must be after checkIn");
   321	        }
   322	        if (req.guests() < 1) {
   323	            throw ApiException.invalid("guests must be at least 1");
   324	        }
   325	        Room room = rooms.stream().filter(r -> r.number() == req.roomNumber()).findFirst()
   326	                .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Room " + req.roomNumber() + " not found"));
   327	        if (req.guests() > room.capacity()) {
   328	            throw new ApiException(422, "CAPACITY_EXCEEDED",
   329	                    "Room " + room.number() + " holds at most " + room.capacity() + " guests");
   330	        }
   331	        boolean taken = reservations.stream().anyMatch(r -> r.room.equals(room)
   332	                && r.status != Status.CANCELLED && r.overlaps(req.checkIn(), req.checkOut()));
   333	        if (taken) {
   334	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Room " + room.number() + " is not available for these dates");
   335	        }
   336	        Pricing.Quote quote = Pricing.quote(room, req.checkIn(), req.checkOut(), req.ratePlan());
   337	        Reservation r = new Reservation(reservations.size() + 1, room, req.guestName(), req.guestEmail(),
   338	                req.guestCpf(), req.checkIn(), req.checkOut(), req.guests(), req.ratePlan(), quote);
   339	        reservations.add(r);
   340	        return r;
   341	    }
   342	
   343	    public synchronized Reservation get(String id) {
   344	        try {
   345	            int n = Integer.parseInt(id);
   346	            if (n >= 1 && n <= reservations.size()) {
   347	                return reservations.get(n - 1);
   348	            }
   349	        } catch (NumberFormatException ignored) {
   350	            // falls through to not found
   351	        }
   352	        throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation " + id + " not found");
   353	    }
   354	
   355	    public synchronized Reservation confirm(String id) {
   356	        Reservation r = get(id);
   357	        requireStatus(r, "confirmed", Status.PENDING);
   358	        r.status = Status.CONFIRMED;
   359	        r.amountPaid = r.total;
   360	        outbox.send(Outbox.Channel.EMAIL, r.guestEmail, EMAIL_SUBJECT, ReceiptFormatter.confirmationEmail(r));
   361	        return r;
   362	    }
   363	
   364	    public synchronized Reservation cancel(String id) {
   365	        Reservation r = get(id);
   366	        requireStatus(r, "cancelled", Status.PENDING, Status.CONFIRMED);
   367	        r.refund = r.ratePlan.refundable() ? r.amountPaid : Money.ZERO;
   368	        r.status = Status.CANCELLED;
   369	        return r;
   370	    }
   371	
   372	    public synchronized Reservation checkIn(String id) {
   373	        Reservation r = get(id);
   374	        requireStatus(r, "checked in", Status.CONFIRMED);
   375	        r.status = Status.CHECKED_IN;
   376	        return r;
   377	    }
   378	
   379	    public synchronized Reservation checkOut(String id) {
   380	        Reservation r = get(id);
   381	        requireStatus(r, "checked out", Status.CHECKED_IN);
   382	        r.status = Status.CHECKED_OUT;
   383	        return r;
   384	    }
   385	
   386	    /** Receipt copy: only for paid reservations. */
   387	    public synchronized Reservation receiptFor(String id) {
   388	        Reservation r = get(id);
   389	        if (!r.status.isPaid()) {
   390	            throw ApiException.notAllowed("Reservation " + r.id + " is " + r.status + " and has no receipt");
   391	        }
   392	        return r;
   393	    }
   394	
   395	    /** Runs a read-only computation over a consistent view of all reservations. */
   396	    public synchronized <T> T read(Function<List<Reservation>, T> fn) {
   397	        return fn.apply(List.copyOf(reservations));
   398	    }
   399	
   400	    private void requireStatus(Reservation r, String action, Status... allowed) {
   401	        for (Status s : allowed) {
   402	            if (r.status == s) return;
   403	        }
   404	        throw ApiException.notAllowed("Reservation " + r.id + " is " + r.status + " and cannot be " + action);
   405	    }
   406	}
