    40	public final class Pricing {
    41	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    42	
    43	    private Pricing() {}
    44	
    45	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    46	
    47	    /** High season: Dec 15 through end of February, and all of July. */
    48	    public static boolean isHighSeason(LocalDate night) {
    49	        Month m = night.getMonth();
    50	        return m == Month.JANUARY || m == Month.FEBRUARY || m == Month.JULY
    51	                || (m == Month.DECEMBER && night.getDayOfMonth() >= 15);
    52	    }
    53	
    54	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    55	        BigDecimal rate = room.nightlyRate();
    56	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    57	    }
    58	
    59	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    60	        BigDecimal subtotal = Money.ZERO;
    61	        int nights = 0;
    62	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    63	            subtotal = Money.round(subtotal.add(nightPrice(room, d)));
    64	            nights++;
    65	        }
    66	        BigDecimal discount = Money.round(subtotal.multiply(plan.discountRate()));
    67	        BigDecimal total = Money.round(subtotal.subtract(discount));
    68	        return new Quote(nights, subtotal, discount, total);
    69	    }
    70	}
